#define wmain unused_original_entry
#include "../baseline/native-ad-replay.cpp"
#undef wmain
#include <chrono>
#include <cmath>
#include <cstdint>
#include <numeric>
struct EdgeCandidate { bool found=false; int outsideY=-1,insideY=-1,nominalY=-1,topFringe=-1,bottomFringe=-1; double support[4]={}; int uvQ[4]={}; int minPersist=0; };
struct Nomination { EdgeCandidate top,bottom; int rows=0,cols=0; uint64_t pairs=0; bool found=false; int cropTop=-1,cropBottom=-1; };
static int Median(std::vector<int> v){if(v.empty())return 0;std::nth_element(v.begin(),v.begin()+v.size()/2,v.end());return v[v.size()/2];}
static int RowMedian(const ActivePictureDiagnosticGrid& g,int row,int c0,int c1){std::vector<int> v;for(int c=c0;c<c1;++c)v.push_back(g.samples[size_t(row)*g.columns+c].luma);return Median(std::move(v));}
static EdgeCandidate ScanEdge(const ActivePictureDiagnosticGrid& g,int rasterHeight,bool top,uint64_t& pairs){
 EdgeCandidate result; if(g.rows<24||g.columns<16)return result;
 const int qsize=g.columns/4; const int outside0=top?0:g.rows-1,outside1=top?1:g.rows-2;
 int exterior[4];for(int q=0;q<4;++q)exterior[q]=Median({RowMedian(g,outside0,q*qsize,(q+1)*qsize),RowMedian(g,outside1,q*qsize,(q+1)*qsize)});
 const int maxDepth=(g.rows-1)/2;
 for(int d=0;d<maxDepth;++d){const int ro=top?d:g.rows-1-d,ri=top?d+1:g.rows-2-d;int supported[4]={},uv[4]={};
  for(int c=0;c<g.columns;++c){const auto&o=g.samples[size_t(ro)*g.columns+c];const auto&i=g.samples[size_t(ri)*g.columns+c];++pairs;if(int(i.luma)-int(o.luma)>=24){const int q=std::min(3,c/qsize);++supported[q];if(std::abs(int(i.chromaU)-int(o.chromaU))>=10||std::abs(int(i.chromaV)-int(o.chromaV))>=10)++uv[q];}}
  bool supportOk=true;for(int q=0;q<4;++q)if(supported[q]<int(std::ceil(.80*qsize)))supportOk=false;if(!supportOk)continue;
  int persist=0;bool persistOk=true;for(int off:{2,4,8}){const int rr=top?ri+off:ri-off;if(rr<0||rr>=g.rows){persistOk=false;break;}for(int q=0;q<4;++q)if(RowMedian(g,rr,q*qsize,(q+1)*qsize)<exterior[q]+16)persistOk=false;if(persistOk)++persist;}
  if(!persistOk||persist<3)continue;
  const int yOutside=static_cast<int>(int64_t(ro)*(rasterHeight-1)/(g.rows-1));const int yInside=static_cast<int>(int64_t(ri)*(rasterHeight-1)/(g.rows-1));
  result.found=true;result.outsideY=yOutside;result.insideY=yInside;result.nominalY=(yOutside+yInside)/2;result.topFringe=std::max(0,std::min(yOutside,yInside)-(rasterHeight/g.rows));result.bottomFringe=std::min(rasterHeight,std::max(yOutside,yInside)+(rasterHeight/g.rows));result.minPersist=persist;
  for(int q=0;q<4;++q){result.support[q]=double(supported[q])/qsize;result.uvQ[q]=uv[q];}return result;
 }
 return result;
}
static Nomination Nominate(const AnalysisLumaSource& s){Nomination n;const auto grid=SampleActivePictureDiagnosticGrid(s);n.rows=grid.rows;n.cols=grid.columns;if(!grid.rows)return n;n.top=ScanEdge(grid,s.height,true,n.pairs);n.bottom=ScanEdge(grid,s.height,false,n.pairs);n.found=n.top.found&&n.bottom.found;if(n.found){n.cropTop=n.top.nominalY;n.cropBottom=n.bottom.nominalY;}return n;}
static void PrintEdge(std::ostream&o,const EdgeCandidate&e){o<<e.found<<','<<e.outsideY<<','<<e.insideY<<','<<e.nominalY<<','<<e.topFringe<<','<<e.bottomFringe<<','<<e.support[0]<<','<<e.support[1]<<','<<e.support[2]<<','<<e.support[3]<<','<<e.uvQ[0]<<','<<e.uvQ[1]<<','<<e.uvQ[2]<<','<<e.uvQ[3]<<','<<e.minPersist;}
struct Synthetic {std::string name;int kind;};
static Frame MakeSynthetic(const std::string&name,int kind){Frame f;f.source.width=3840;f.source.height=2160;f.source.rowBytes=3840*4;f.source.chromaRowBytes=0;f.source.format=AnalysisLumaFormat::NativeRgb;f.source.encoding=VideoFrameEncoding::BGRA_8BIT;f.source.colorspace=ColorSpace::REC_709;f.source.rgbBitAlignment=1;f.bytes.resize(size_t(f.source.rowBytes)*f.source.height);auto gray=[&](int x,int y){if(kind==0){if(y<302)return 25+(y*90/302);if(y<1856)return 200+((x/12+y/10)%3)*5;return 12;}if(kind==1)return 130;if(kind==2){if(y<302)return 8;if(y<1856)return 22;return 5;}if(kind==3){if(y>=296&&y<304)return 245;return 20;}if(kind==4){return (y>=796&&y<820)?240:80;}if(kind==5){if(y<302)return 25+(y*90/302);if(y<1856)return 200+((x/12+y/10)%3)*5;if(y>1880&&y<1920&&x>900&&x<2940)return 250;return 12;}if(kind==7){if(y<302)return 25+(y*90/302);if(y<1856)return 200+((x/12+y/10)%3)*5;return 12;}return 30;};for(int y=0;y<f.source.height;++y)for(int x=0;x<f.source.width;++x){const uint8_t v=uint8_t(std::clamp(gray(x,y),0,255));const size_t p=size_t(y)*f.source.rowBytes+size_t(x)*4;f.bytes[p]=f.bytes[p+1]=f.bytes[p+2]=v;f.bytes[p+3]=255;}f.source.data=f.bytes.data();f.source.dataBytes=f.bytes.size();f.source.range=AnalysisLumaRange::Full;return f;}
int wmain(int argc,wchar_t**argv){try{if(argc!=3)throw std::runtime_error("usage: grid-relative CAPTURE OUTPUT");fs::path cap=argv[1],out=argv[2];std::ofstream csv(out/L"candidate.csv");csv<<std::setprecision(6)<<"frame,sequence,top_found,top_outer,top_inner,top_nominal_y,top_fringe_min,top_fringe_max,top_q0,top_q1,top_q2,top_q3,top_uv0,top_uv1,top_uv2,top_uv3,top_persist,bottom_found,bottom_outer,bottom_inner,bottom_nominal_y,bottom_fringe_min,bottom_fringe_max,bottom_q0,bottom_q1,bottom_q2,bottom_q3,bottom_uv0,bottom_uv1,bottom_uv2,bottom_uv3,bottom_persist,paired_comparisons,grid_samples,grid_rows,grid_cols,grid_us,candidate_bottom\n";std::vector<fs::path> paths;for(const auto&e:fs::directory_iterator(cap))if(e.path().extension()==L".bin")paths.push_back(e.path());std::sort(paths.begin(),paths.end());int i=0;std::vector<int> tops,bottoms;uint64_t totalPairs=0,totalSamples=0;double us=0;for(const auto&p:paths){auto f=Read(p);f.source.data=f.bytes.data();auto a=std::chrono::steady_clock::now();const auto n=Nominate(f.source);auto b=std::chrono::steady_clock::now();const double dt=std::chrono::duration<double,std::micro>(b-a).count();++i;us+=dt;totalPairs+=n.pairs;totalSamples+=uint64_t(n.rows)*n.cols;if(n.found){tops.push_back(n.cropTop);bottoms.push_back(n.cropBottom);}csv<<i<<','<<f.identity.acceptedSequence<<',';PrintEdge(csv,n.top);csv<<',';PrintEdge(csv,n.bottom);csv<<','<<n.pairs<<','<<n.rows*n.cols<<','<<n.rows<<','<<n.cols<<','<<dt<<','<<n.cropBottom<<'\n';}
 auto synth=out/L"synthetic.csv";std::ofstream so(synth);so<<std::setprecision(6)<<"case,top_found,top_outer,top_inner,top_nominal_y,top_fringe_min,top_fringe_max,top_q0,top_q1,top_q2,top_q3,top_uv0,top_uv1,top_uv2,top_uv3,top_persist,bottom_found,bottom_outer,bottom_inner,bottom_nominal_y,bottom_fringe_min,bottom_fringe_max,bottom_q0,bottom_q1,bottom_q2,bottom_q3,bottom_uv0,bottom_uv1,bottom_uv2,bottom_uv3,bottom_persist,paired_comparisons,grid_samples,grid_rows,grid_cols,crop_candidate_top,crop_candidate_bottom\n";for(auto s:std::vector<Synthetic>{{"gradient_exterior_real_aperture",0},{"flat_full_raster",1},{"near_black_low_contrast_picture",2},{"thin_bright_line",3},{"internal_divider_only",4},{"gradient_with_subtitle_in_bars",5},{"uniform_full_raster",6},{"authored_full_raster_scene_bands_pixel_alias",7}}){auto f=MakeSynthetic(s.name,s.kind);auto n=Nominate(f.source);so<<s.name<<',';PrintEdge(so,n.top);so<<',';PrintEdge(so,n.bottom);so<<','<<n.pairs<<','<<n.rows*n.cols<<','<<n.rows<<','<<n.cols<<','<<(n.found?n.cropTop:-1)<<','<<(n.found?n.cropBottom:-1)<<'\n';}
 std::cout<<"frames="<<i<<"; found_both="<<tops.size()<<"; nominal_top_min_median_max="<<(tops.empty()?0:*std::min_element(tops.begin(),tops.end()))<<','<<(tops.empty()?0:Median(tops))<<','<<(tops.empty()?0:*std::max_element(tops.begin(),tops.end()))<<"; nominal_bottom_min_median_max="<<(bottoms.empty()?0:*std::min_element(bottoms.begin(),bottoms.end()))<<','<<(bottoms.empty()?0:Median(bottoms))<<','<<(bottoms.empty()?0:*std::max_element(bottoms.begin(),bottoms.end()))<<"; total_grid_samples="<<totalSamples<<"; paired_comparisons="<<totalPairs<<"; mean_us="<<(i?us/i:0)<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}




